 const applyCommands=(commands:GraphCommand[])=>{const state:GraphState={...rootGraph.current,values:valuesRef.current,revision:graphRevision.current,resourceBindings:resourceBindingsRef.current};const next=applyGraphTransaction(state,{baseRevision:state.revision,commands},{requests});replaceRoot({nodes:next.nodes,edges:next.edges});trackDeletedRequests(state.nodes,next.nodes);valuesRef.current=next.values;writeValues(next.values);resourceBindingsRef.current=next.resourceBindings??[];setResourceBindings(resourceBindingsRef.current);if(entryId&&!next.nodes.some(node=>node.id===entryId))setEntryId('');};
