   const commands:GraphCommand[]=[{op:'create',id:profileId,kind:'profile',label:'我的浏览器画像',data:defaultResourceData('profile')},{op:'create',id:sessionId,kind:'browserSession',label:'固定浏览器环境',data:{session:{name:'固定浏览器环境',profileId,persist:false}}}];
