 const undoEdit=()=>{const previous=past.current.pop();if(!previous)return;lastEdit.current={key:'',time:0};dragStart.current=null;future.current=[historySnapshot(),...future.current];graphRevision.current++;replaceRoot(previous,false);valuesRef.current=previous.values;writeValues(previous.values);resourceBindingsRef.current=previous.resourceBindings??[];setResourceBindings(resourceBindingsRef.current);defaultsRef.current=previous.defaults;setResourceDefaults(previous.defaults);suppressed.current=new Set(previous.suppressed);entryRef.current=previous.entryId;setEntryId(previous.entryId);setScopePath([]);setSelectedId(null);setHistoryVersion(version=>version+1);};
 const redoEdit=()=>{const next=future.current.shift();if(!next)return;lastEdit.current={key:'',time:0};dragStart.current=null;past.current=[...past.current,historySnapshot()];graphRevision.current++;replaceRoot(next,false);valuesRef.current=next.values;writeValues(next.values);resourceBindingsRef.current=next.resourceBindings??[];setResourceBindings(resourceBindingsRef.current);defaultsRef.current=next.defaults;setResourceDefaults(next.defaults);suppressed.current=new Set(next.suppressed);entryRef.current=next.entryId;setEntryId(next.entryId);setScopePath([]);setSelectedId(null);setHistoryVersion(version=>version+1);};
 const wrapSteps=(kind:'loop'|'subflow',all=false)=>{const ids=all?nodes.filter(node=>!isResourceKind(node.data.kind)).map(node=>node.id):nodes.filter(node=>node.selected||node.id===selectedId).filter(node=>!isResourceKind(node.data.kind)).map(node=>node.id);if(!ids.length){tell('先框选需要组合的步骤。');return;}try{applyCommands([{op:'wrap',nodeIds:ids,id:`${kind}-${crypto.randomUUID().slice(0,12)}`,label:kind==='loop'?'重复这些步骤':'我的子流程',kind,count:kind==='loop'?3:1}]);setSelectedId(null);tell(kind==='loop'?'已建立重复区域，可在方块中修改次数。':'已封装为子流程，可打开编辑内部步骤。');}catch(error){tell(textOf(error),true);}};
 const openSubflow=(id:string)=>{if(!graph.current.nodes.find(node=>node.id===id)?.data.loop)return;setScopePath(old=>[...old,id]);setSelectedId(null);setExpanded(new Set());setTimeout(fit,20);};
 const patchNode=(id:string,patch:Partial<BlockData>)=>setGraph({nodes:graph.current.nodes.map(node=>node.id===id?{...node,data:{...node.data,...patch}}:node),edges:graph.current.edges},true,`field:${id}`);
 const resourceState=useMemo(()=>({defaults:resourceDefaults,nodes:allProjectNodes(rootGraph.current.nodes),disabled:activeRun||checking||repairLoading,onPatch:patchNode,onOpenSubflow:openSubflow,onLocate:locate,onCreateEnvironment:(id:string)=>createEnvironment(id),onTestProxy:async(id:string)=>{const node=allProjectNodes(rootGraph.current.nodes).find(node=>node.id===id);if(!node?.data.proxy)return {ok:false,error:'代理方块已不存在。'};try{const result=await postJSON<{status:string;durationMs:number;ip?:string;message?:string}>('/api/proxy/test',{proxy:node.data.proxy});return {ok:result.status==='success'||result.status==='ok',durationMs:result.durationMs,exitIp:result.ip,error:result.message};}catch(error){return {ok:false,error:textOf(error)};}}}),[projectNodes,resourceDefaults,scopePath,activeRun,checking,repairLoading,requests,locate]);
 void historyVersion;
 const sendChat=async(text:string)=>{
  if(chatBusy)return;
  if(!config.baseUrl.trim()||!config.apiKey.trim()||!config.model.trim()){setRightTab('agent');tell('先填写模型地址、API Key 和模型名称，再开始对话。');return;}
  const user:ChatMessage={id:crypto.randomUUID(),role:'user',content:text,status:'completed',createdAt:Date.now()},replyId=crypto.randomUUID();
  let messages=[...chatRef.current,user];setChatMessages([...messages,{id:replyId,role:'assistant',content:'',status:'pending'}]);setChatCollapsed(false);
  const controller=new AbortController(),rev=epoch.current,targetPath=[...scopePathRef.current];chatAbort.current=controller;setChatBusy(true);setChatStatus('正在准备画布资料');
  try{
   const proxy=text.match(/socks5:\/\/[^\s]+/i)?.[0]||(/代理|proxy/i.test(text)?text.match(/https?:\/\/[^\s]+/i)?.[0]:undefined);
   if(proxy){const id=`proxy-${crypto.randomUUID().slice(0,12)}`;applyCommands([{op:'create',id,kind:'proxy',label:'我的代理',data:{proxy:{url:proxy,rotation:'fixed'}}}]);messages=[...messages.slice(0,-1),{...user,content:`${text.replace(proxy,'[代理连接已保存在本地]')}。本地代理方块编号为 ${id}，请使用它，无需再次填写凭据。`}];}
   const state:GraphState={...rootGraph.current,values:valuesRef.current,revision:graphRevision.current,resourceBindings:resourceBindingsRef.current};
   const selected=graph.current.nodes.filter(node=>node.selected||node.id===selectedId).map(node=>node.id),snapshot=buildChatSnapshot(state,requests,selected,messages,{issues,events});
   const plan=await runAgentChat({...config},snapshot.input,controller.signal,{onProgress:progress=>{if(chatAbort.current===controller)setChatStatus(analysisStageLabels[progress.stage]);}});
   if(controller.signal.aborted||rev!==epoch.current||chatAbort.current!==controller)return;
   if(JSON.stringify(targetPath)!==JSON.stringify(scopePathRef.current))throw new Error('当前编辑范围已改变，请回到原范围后重新发送要求。');
   const current:GraphState={...rootGraph.current,values:valuesRef.current,revision:graphRevision.current,resourceBindings:resourceBindingsRef.current};
   const next=applyChatPlan(current,snapshot,plan,requests);
   if(plan.commands.length){replaceRoot({nodes:next.nodes,edges:next.edges});trackDeletedRequests(current.nodes,next.nodes);valuesRef.current=next.values;writeValues(next.values);resourceBindingsRef.current=next.resourceBindings??[];setResourceBindings(next.resourceBindings??[]);}
   const nodeIds=[...new Set(plan.commands.flatMap(command=>'nodeId'in command?[command.nodeId]:'id'in command&&command.op==='create'?[command.id]:[]))].slice(0,8);
   setChatMessages(old=>old.map(message=>message.id===replyId?{...message,content:plan.message,status:'completed',questions:plan.questions,runIntent:plan.runIntent,nodeIds,changeCount:plan.commands.length}:message));setChatStatus('');
   if(plan.runIntent&&/^(?:请)?(?:开始|立即)?(?:运行|执行)(?:当前|这个|整个)?(?:流程|项目)?(?:一次)?[。！!\s]*$|^run(?: flow)?$/i.test(text.trim()))void run();
   else if(plan.runIntent)tell('流程已准备，可点击「运行流程」开始执行。');
  }catch(error){if(rev===epoch.current){const cancelled=controller.signal.aborted;setChatMessages(old=>old.map(message=>message.id===replyId?{...message,content:cancelled?'已停止，本次未完成的建议不会应用。':'本次要求未能完成。',status:cancelled?'cancelled':'failed',error:cancelled?undefined:textOf(error)}:message));}}
  finally{if(chatAbort.current===controller){chatAbort.current=null;setChatBusy(false);setChatStatus('');}}
 };
 const retryChat=(id:string)=>{const index=chatMessages.findIndex(message=>message.id===id);const user=chatMessages.slice(0,index).reverse().find(message=>message.role==='user');if(user)void sendChat(user.content);};
 useEffect(()=>{const handle=(event:KeyboardEvent)=>{const target=event.target as HTMLElement;if(target.closest('input,textarea,select,[contenteditable=true]')||!(event.ctrlKey||event.metaKey)||activeRun)return;if(event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redoEdit():undoEdit();}else if(event.key.toLowerCase()==='y'){event.preventDefault();redoEdit();}};window.addEventListener('keydown',handle);return()=>window.removeEventListener('keydown',handle);},[activeRun]);
 const importPhase=uploadProgress?.phase??'creating',confirmedBytes=uploadProgress?.receivedBytes??0,uploadSize=uploadProgress?.size??uploadRetry.current?.file.size??0;
