 const uploadPercent=uploadSize?Math.floor(confirmedBytes/uploadSize*100):0,importSeconds=Math.max(0,Math.floor((uploadNow-(uploadProgress?.startedAt??uploadNow))/1000)),phaseSeconds=Math.max(0,Math.floor((uploadNow-(uploadProgress?.phaseStartedAt??uploadNow))/1000));
 const importTitle=importPhase==='compressing'?'正在本地压缩 HAR…':importPhase==='uploading'?'正在上传 HAR…':importPhase==='parsing'?'服务器正在解析 HAR…':importPhase==='result'?'正在读取解析结果…':'正在建立上传任务…';
 const importCaption=importPhase==='compressing'?`原始 ${(originalSize/1048576).toFixed(1)} MiB · 压缩已用时 ${phaseSeconds} 秒`:importPhase==='uploading'?`${uploadPercent}% · 已确认 ${(confirmedBytes/1048576).toFixed(1)} / ${(uploadSize/1048576).toFixed(1)} MiB · 用时 ${importSeconds} 秒`:importPhase==='parsing'?`上传完成 · 解析已等待 ${phaseSeconds} 秒`:importPhase==='result'?`解析完成 · 正在读取结果 ${phaseSeconds} 秒`:`正在连接服务器 · 已等待 ${importSeconds} 秒`;
